static bool frame_command_set_text(const uint8_t *p, uint32_t size) {
    if (size < UI_WIRE_SET_TEXT_ORIGINAL) return false;
    uint32_t header = ui_wire_set_text_header_size(p);
    if (header < UI_WIRE_SET_TEXT_ORIGINAL || header % 4 || header > size) return false;
    uint32_t spans_stride = ui_wire_set_text_spans_stride(p);
    if (spans_stride < UI_WIRE_TEXT_SPAN_ORIGINAL || spans_stride % 4) return false;
    ui_wire_set_text h;
    ui_wire_set_text_read(p, header < UI_WIRE_SET_TEXT_SIZE ? header : UI_WIRE_SET_TEXT_SIZE, &h);
    uint64_t off = header;
    off += (uint64_t)h.span_count * spans_stride;
    if (h.strings_bytes % 4) return false;
    off += h.strings_bytes;
    off += ui_wire_pad4(h.ellipsis_bytes);
    off += ui_wire_pad4(h.chunk_bytes);
    return off <= size;
}

